    {
      file: "02-co2-monitor.ino",
      name: "co2 monitor",
      description: "office air quality, as one big number",
      source: "/*\n * 02-co2-monitor.ino - office air quality, as one big number.\n *\n * Layout is the pattern most things on a 0.96\" panel should use: a small\n * label, one large number readable from a few feet away, and a sparkline of\n * where it has been. Above the threshold the whole panel inverts, which is\n * what actually catches your eye from across a desk.\n *\n * Hardware: Sensirion SCD40/SCD41 on the same I2C bus as the display\n * (sensor 0x62, display 0x3C - no conflict, no extra pins).\n *\n * As written it synthesises a plausible ppm curve so it animates in the\n * simulator with no sensor attached. For the real thing, drop in the\n * SparkFun_SCD4x or Sensirion I2C SCD4x library and replace readCO2().\n */\n#include <Wire.h>\n#include <Adafruit_GFX.h>\n#include <Adafruit_SSD1306.h>\n\n#define OLED_RESET   -1\n#define OLED_ADDR    0x3C\n\n#define WARN_PPM     1000   // above this the room makes you sleepy\n#define HISTORY      64     // one sample per 2 px across the panel\n\nAdafruit_SSD1306 display(128, 64, &Wire, OLED_RESET);\n\nint history[HISTORY];\nint historyCount = 0;\nunsigned long lastSample = 0;\n\nint readCO2() {\n  // Stand-in for scd4x.getCO2(): a slow drift with a shorter ripple on top,\n  // so the sparkline has something to show.\n  float t = millis() / 1000.0;\n  float slow = sin(t / 30.0) * 420.0;\n  float fast = sin(t / 4.0) * 45.0;\n  return (int)(900.0 + slow + fast);\n}\n\nvoid pushSample(int ppm) {\n  if (historyCount < HISTORY) {\n    history[historyCount++] = ppm;\n  } else {\n    for (int i = 1; i < HISTORY; i++) history[i - 1] = history[i];\n    history[HISTORY - 1] = ppm;\n  }\n}\n\nvoid drawSparkline(int x, int y, int w, int h) {\n  if (historyCount < 2) return;\n\n  int lo = history[0];\n  int hi = history[0];\n  for (int i = 1; i < historyCount; i++) {\n    if (history[i] < lo) lo = history[i];\n    if (history[i] > hi) hi = history[i];\n  }\n  if (hi - lo < 40) hi = lo + 40;   // keep a flat line from filling the box\n\n  int prevX = 0;\n  int prevY = 0;\n  for (int i = 0; i < historyCount; i++) {\n    int px = x + (i * (w - 1)) / (HISTORY - 1);\n    int py = y + h - 1 - ((history[i] - lo) * (h - 1)) / (hi - lo);\n    if (i > 0) display.drawLine(prevX, prevY, px, py, SSD1306_WHITE);\n    prevX = px;\n    prevY = py;\n  }\n\n  // Mark the threshold if it falls inside the window.\n  if (WARN_PPM > lo && WARN_PPM < hi) {\n    int wy = y + h - 1 - ((WARN_PPM - lo) * (h - 1)) / (hi - lo);\n    for (int px = x; px < x + w; px += 4) display.drawPixel(px, wy, SSD1306_WHITE);\n  }\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Wire.begin();\n  Wire.setClock(400000);\n\n  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {\n    Serial.println(F(\"no display\"));\n    for (;;) delay(1000);\n  }\n\n  display.clearDisplay();\n  display.setTextColor(SSD1306_WHITE);\n  display.setCursor(0, 0);\n  display.println(F(\"warming up\"));\n  display.display();\n}\n\nvoid loop() {\n  if (millis() - lastSample >= 500) {\n    lastSample = millis();\n    pushSample(readCO2());\n  }\n\n  int ppm = historyCount ? history[historyCount - 1] : 0;\n\n  display.clearDisplay();\n\n  // Label\n  display.setTextSize(1);\n  display.setCursor(0, 0);\n  display.print(F(\"CO2\"));\n\n  // Trend over the last 10 s, which is a long enough window to agree with\n  // what the sparkline below is showing.\n  if (historyCount > 20) {\n    int delta = history[historyCount - 1] - history[historyCount - 21];\n    display.setCursor(30, 0);\n    if (delta > 15) display.print(F(\"rising\"));\n    else if (delta < -15) display.print(F(\"falling\"));\n    else display.print(F(\"steady\"));\n  }\n\n  display.setCursor(104, 0);\n  display.print(F(\"ppm\"));\n\n  // The number itself: size 3 is 18x24 px per glyph, about the smallest\n  // that stays readable from across a desk.\n  display.setTextSize(3);\n  int digits = ppm >= 1000 ? 4 : (ppm >= 100 ? 3 : 2);\n  display.setCursor(64 - (digits * 18) / 2, 13);\n  display.print(ppm);\n\n  drawSparkline(0, 44, 128, 20);\n\n  // Peripheral-vision alarm.\n  display.invertDisplay(ppm > WARN_PPM);\n\n  display.display();\n  delay(100);\n}\n",
    },
    {
      file: "03-parking-sensor.ino",
      name: "parking sensor",
      description: "garage stop sign",
      source: "/*\n * 03-parking-sensor.ino - garage stop sign.\n *\n * Mounted at windshield height you are about three feet from the panel, so\n * size 4 digits (24x32 px, ~5.4 mm tall) are comfortably readable. Three\n * states, and only one of them is on screen at a time:\n *\n *   approaching  distance in inches, plus a bar that shrinks as you close\n *   in position  full-screen STOP, inverted and blinking\n *   too far      a hint, so the panel is not just blank\n *\n * Hardware: VL53L1X time-of-flight sensor (I2C 0x29, shares the bus with the\n * display). A HC-SR04 ultrasonic works too but is noisier below 6 inches.\n *\n * As written it animates a car pulling in so the sketch demos on its own.\n * With a real sensor, replace readDistanceInches() with the library call and\n * delete rehearsedApproach().\n */\n#include <Wire.h>\n#include <Adafruit_GFX.h>\n#include <Adafruit_SSD1306.h>\n\n#define OLED_RESET    -1\n#define OLED_ADDR     0x3C\n\n#define STOP_INCHES   12    // where the bumper should end up\n#define SLOW_INCHES   36    // start paying attention\n#define MAX_INCHES    96    // beyond this, nothing is arriving\n\nAdafruit_SSD1306 display(128, 64, &Wire, OLED_RESET);\n\n// A 20-second loop: roll in from 8 feet, stop, sit, then pull out again.\nint rehearsedApproach() {\n  unsigned long t = millis() % 20000;\n  if (t < 9000)  return MAX_INCHES - (int)((t * (MAX_INCHES - STOP_INCHES + 2)) / 9000);\n  if (t < 15000) return STOP_INCHES - 2;\n  return STOP_INCHES - 2 + (int)(((t - 15000) * (MAX_INCHES - STOP_INCHES)) / 5000);\n}\n\nint readDistanceInches() {\n  // Real sensor:  return sensor.getDistance() / 25.4;\n  return rehearsedApproach();\n}\n\nvoid drawApproach(int inches) {\n  display.setTextSize(1);\n  display.setCursor(0, 0);\n  display.print(F(\"PULL FORWARD\"));\n\n  // The number, centred. Size 4 is 24 px per glyph.\n  display.setTextSize(4);\n  int digits = inches >= 10 ? 2 : 1;\n  display.setCursor(64 - (digits * 24) / 2 - 12, 16);\n  display.print(inches);\n\n  display.setTextSize(2);\n  display.setCursor(64 + (digits * 24) / 2 - 6, 28);\n  display.print(F(\"in\"));\n\n  // A bar that empties as the bumper closes on the mark.\n  int span = SLOW_INCHES - STOP_INCHES;\n  int over = inches - STOP_INCHES;\n  if (over < 0) over = 0;\n  if (over > span) over = span;\n  int filled = 124 - (over * 124) / span;\n\n  display.drawRect(0, 54, 128, 10, SSD1306_WHITE);\n  display.fillRect(2, 56, filled, 6, SSD1306_WHITE);\n}\n\nvoid drawStop(bool blinkOn) {\n  // Whole panel inverted, so it reads as a block of light in the mirror.\n  display.fillScreen(SSD1306_WHITE);\n  if (!blinkOn) return;\n\n  display.setTextColor(SSD1306_BLACK, SSD1306_WHITE);\n  display.setTextSize(4);\n  display.setCursor(64 - (4 * 24) / 2, 18);\n  display.print(F(\"STOP\"));\n  display.setTextColor(SSD1306_WHITE);\n}\n\nvoid drawIdle() {\n  display.setTextSize(1);\n  display.setCursor(22, 28);\n  display.print(F(\"waiting for car\"));\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Wire.begin();\n  Wire.setClock(400000);\n\n  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {\n    Serial.println(F(\"no display\"));\n    for (;;) delay(1000);\n  }\n  display.setTextColor(SSD1306_WHITE);\n}\n\nvoid loop() {\n  int inches = readDistanceInches();\n\n  display.clearDisplay();\n  display.invertDisplay(false);\n\n  if (inches <= STOP_INCHES) {\n    drawStop((millis() / 400) % 2 == 0);\n  } else if (inches <= MAX_INCHES) {\n    drawApproach(inches);\n  } else {\n    drawIdle();\n  }\n\n  display.display();\n  delay(50);\n}\n",
    },
    {
      file: "04-build-status.ino",
      name: "build status",
      description: "CI on the desk",
      source: "/*\n * 04-build-status.ino - CI on the desk.\n *\n * A tick or a cross large enough to read peripherally, the branch under it,\n * and a count of PRs waiting on you. Red inverts the panel, which is the\n * whole point: you notice it without looking at it.\n *\n * The pixel budget is why the mark is drawn with lines rather than set in\n * text -- at this size a glyph would be a smudge, and a 40 px tick is not.\n *\n * Hardware: any Wi-Fi capable ESP32. Poll the GitHub API roughly every 30 s\n * (well inside the unauthenticated rate limit) and parse the conclusion of\n * the latest check suite. Here the states are rehearsed on a timer.\n */\n#include <Wire.h>\n#include <Adafruit_GFX.h>\n#include <Adafruit_SSD1306.h>\n\n#define OLED_RESET  -1\n#define OLED_ADDR   0x3C\n\n#define ST_PASS     0\n#define ST_FAIL     1\n#define ST_RUNNING  2\n\nAdafruit_SSD1306 display(128, 64, &Wire, OLED_RESET);\n\nconst char *BRANCH = \"main\";\nint reviewsWaiting = 2;\n\nint fetchStatus() {\n  // Real version: HTTPClient GET the check-suite conclusion and map it here.\n  unsigned long phase = (millis() / 6000) % 3;\n  if (phase == 0) return ST_PASS;\n  if (phase == 1) return ST_RUNNING;\n  return ST_FAIL;\n}\n\nvoid drawTick(int cx, int cy, uint16_t color) {\n  // Three strokes each, so the mark has weight at a distance.\n  for (int i = 0; i < 3; i++) {\n    display.drawLine(cx - 16, cy + i, cx - 5, cy + 11 + i, color);\n    display.drawLine(cx - 5, cy + 11 + i, cx + 16, cy - 10 + i, color);\n  }\n}\n\nvoid drawCross(int cx, int cy, uint16_t color) {\n  for (int i = 0; i < 3; i++) {\n    display.drawLine(cx - 13 + i, cy - 13, cx + 13 + i, cy + 13, color);\n    display.drawLine(cx + 13 + i, cy - 13, cx - 13 + i, cy + 13, color);\n  }\n}\n\nvoid drawSpinner(int cx, int cy, uint16_t color) {\n  // Two arcs chasing each other, stepped 12 times per revolution.\n  int step = (millis() / 80) % 12;\n  for (int i = 0; i < 12; i++) {\n    int lit = (i == step) || (i == (step + 6) % 12);\n    if (!lit) continue;\n    float a = (i * 3.14159 * 2.0) / 12.0;\n    int x = cx + (int)(cos(a) * 16.0);\n    int y = cy + (int)(sin(a) * 16.0);\n    display.fillCircle(x, y, 2, color);\n  }\n  display.drawCircle(cx, cy, 16, color);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Wire.begin();\n  Wire.setClock(400000);\n\n  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {\n    Serial.println(F(\"no display\"));\n    for (;;) delay(1000);\n  }\n  display.setTextColor(SSD1306_WHITE);\n}\n\nvoid loop() {\n  int status = fetchStatus();\n  bool failing = (status == ST_FAIL);\n\n  display.clearDisplay();\n\n  // On a failure the panel inverts, so the mark is drawn in black-on-lit.\n  uint16_t ink = failing ? SSD1306_BLACK : SSD1306_WHITE;\n  if (failing) display.fillScreen(SSD1306_WHITE);\n  display.setTextColor(ink, failing ? SSD1306_WHITE : SSD1306_BLACK);\n\n  if (status == ST_PASS) drawTick(34, 28, ink);\n  else if (status == ST_FAIL) drawCross(34, 28, ink);\n  else drawSpinner(34, 28, ink);\n\n  display.setTextSize(1);\n  display.setCursor(60, 12);\n  if (status == ST_PASS) display.print(F(\"passing\"));\n  else if (status == ST_FAIL) display.print(F(\"FAILED\"));\n  else display.print(F(\"running\"));\n\n  display.setCursor(60, 24);\n  display.print(BRANCH);\n\n  display.drawFastHLine(0, 50, 128, ink);\n  display.setCursor(0, 55);\n  display.print(reviewsWaiting);\n  display.print(F(\" PRs need review\"));\n\n  display.display();\n  delay(80);\n}\n",
    },
    {
      file: "05-readability-ruler.ino",
      name: "readability ruler",
      description: "what actually fits, and how far away you can",
      source: "/*\n * 05-readability-ruler.ino - what actually fits, and how far away you can\n * read it.\n *\n * Not a project: a measuring stick. The active area of this panel is about\n * 21.7 x 10.9 mm, so one pixel is roughly 0.17 mm. That makes the built-in\n * 5x7 font work out as:\n *\n *   size 1   6x8 px    1.4 mm tall   21 chars x 8 lines   desk distance\n *   size 2   12x16 px  2.7 mm tall   10 chars x 4 lines   arm's length\n *   size 3   18x24 px  4.1 mm tall   7 chars x 2 lines    a few feet\n *   size 4   24x32 px  5.4 mm tall   5 chars x 2 lines    across a room\n *\n * Run this, then look at the panel from where the finished thing will live.\n * Whichever row you can still read is the size your project gets to use --\n * and that, more than anything else, decides what can go on this screen.\n */\n#include <Wire.h>\n#include <Adafruit_GFX.h>\n#include <Adafruit_SSD1306.h>\n\n#define OLED_RESET -1\n#define OLED_ADDR  0x3C\n\nAdafruit_SSD1306 display(128, 64, &Wire, OLED_RESET);\n\nint page = 0;\n\nvoid drawSizeSamples() {\n  display.setTextSize(1);\n  display.setCursor(0, 0);\n  display.print(F(\"1: 21x8 chars 1.4mm\"));\n\n  display.setTextSize(2);\n  display.setCursor(0, 10);\n  display.print(F(\"2: 2.7mm\"));\n\n  display.setTextSize(3);\n  display.setCursor(0, 28);\n  display.print(F(\"3 4.1\"));\n\n  display.setTextSize(4);\n  display.setCursor(0, 32 + 0);\n  // Size 4 needs the bottom half to itself; show it on its own page instead.\n}\n\nvoid drawBigSample() {\n  display.setTextSize(1);\n  display.setCursor(0, 0);\n  display.print(F(\"size 4: 5 chars wide\"));\n\n  display.setTextSize(4);\n  display.setCursor(4, 20);\n  display.print(F(\"88:88\"));\n}\n\nvoid drawGrid() {\n  display.setTextSize(1);\n  display.setCursor(0, 0);\n  display.print(F(\"128x64 grid, 8px\"));\n\n  for (int x = 0; x <= 128; x += 8) display.drawFastVLine(x, 10, 54, SSD1306_WHITE);\n  for (int y = 10; y <= 63; y += 8) display.drawFastHLine(0, y, 128, SSD1306_WHITE);\n\n  // Corner markers, to check nothing is cropped by the panel bezel.\n  display.fillRect(0, 10, 3, 3, SSD1306_WHITE);\n  display.fillRect(125, 10, 3, 3, SSD1306_WHITE);\n  display.fillRect(0, 61, 3, 3, SSD1306_WHITE);\n  display.fillRect(125, 61, 3, 3, SSD1306_WHITE);\n}\n\nvoid drawPrimitives() {\n  display.setTextSize(1);\n  display.setCursor(0, 0);\n  display.print(F(\"GFX primitives\"));\n\n  display.drawRect(2, 12, 28, 20, SSD1306_WHITE);\n  display.fillRect(34, 12, 28, 20, SSD1306_WHITE);\n  display.drawRoundRect(66, 12, 28, 20, 6, SSD1306_WHITE);\n  display.fillRoundRect(98, 12, 28, 20, 6, SSD1306_WHITE);\n\n  display.drawCircle(14, 48, 12, SSD1306_WHITE);\n  display.fillCircle(46, 48, 12, SSD1306_WHITE);\n  display.drawTriangle(66, 60, 80, 36, 94, 60, SSD1306_WHITE);\n  display.fillTriangle(98, 60, 112, 36, 126, 60, SSD1306_WHITE);\n}\n\nvoid setup() {\n  Serial.begin(115200);\n  Wire.begin();\n  Wire.setClock(400000);\n\n  if (!display.begin(SSD1306_SWITCHCAPVCC, OLED_ADDR)) {\n    Serial.println(F(\"no display\"));\n    for (;;) delay(1000);\n  }\n  display.setTextColor(SSD1306_WHITE);\n}\n\nvoid loop() {\n  page = (millis() / 3000) % 4;\n\n  display.clearDisplay();\n  if (page == 0) drawSizeSamples();\n  else if (page == 1) drawBigSample();\n  else if (page == 2) drawGrid();\n  else drawPrimitives();\n  display.display();\n\n  delay(200);\n}\n",
    }
